solution:
def shape_episode(rewards,potentials,gamma):
    if len(potentials)!=len(rewards)+1 or potentials[-1]!=0:
        raise ValueError('Need one more potential and terminal zero')
    return [r+gamma*potentials[t+1]-potentials[t] for t,r in enumerate(rewards)]
